import{uid}from'./model.js';
import{ABILITY_TEMPLATES,previewDamageRules}from'./effect-recipes.js';
import{ABILITY_TRIGGERS,ABILITY_CONDITIONS,ABILITY_EFFECTS}from'./creature-model.js';
import{nativeAbilityProfile,abilityDefinitions,validateNativeAbility}from'./ability-native.js';
import{decodeCreatureText}from'./expanded-form-native.js';
export function abilityMaker(api){const $=s=>document.querySelector(s),esc=api.esc;let context=null;const data=()=>{const d=api.project().abilityStudio??={version:1,abilities:[],nativeIds:{}};d.nativeIds??={};return d;};
 async function open(){context=api.session()?await api.game().context():null;const p=context&&nativeAbilityProfile(context.reader);api.modal('Ability maker',`<p>Create reusable abilities with separate native IDs. Existing ability slots are retained. Assign a compiled ability to a Pokémon’s first, second or hidden slot.</p><div class="smart-actions"><button id="abilityMakerNew" type="button">＋ New ability</button>${p?.existing.length?'<button id="abilityMakerImport" type="button">Import compiled ability recipes</button>':''}</div><p>${p?'Native compiler available for this ROM: damage/type/contact/immunity rules, switch-in weather or Intimidate, and end-turn Rain Dish or Speed Boost. Other effects remain designs.':'Native ability compilation is not verified for the opened ROM. Designs can still be saved.'}</p>${abilityDefinitions(api.project()).map(a=>`<article class="event-step"><b>${esc(a.name)}</b><p>${esc(a.description||'')}</p><small>${a.native?.enabled?'Native ID '+a.native.id+' · Pokémon '+a.native.species+' · slot '+(a.native.slot+1):'Design only'}</small><button data-ability-maker-edit="${esc(a.id)}" type="button">Edit ability</button></article>`).join('')}`,null,'Done');$('#abilityMakerNew').onclick=()=>edit({id:uid(),name:'New ability',description:'',rules:[],native:{enabled:false,name:'New ability',species:95,slot:0}});for(const b of document.querySelectorAll('[data-ability-maker-edit]'))b.onclick=()=>edit(abilityDefinitions(api.project()).find(a=>a.id===b.dataset.abilityMakerEdit));if($('#abilityMakerImport'))$('#abilityMakerImport').onclick=()=>{api.change(()=>{for(const old of p.existing){if(abilityDefinitions(api.project()).some(a=>a.id===old.owner))continue;const a=structuredClone(old.spec);a.native.sourceHash=context.hash;a.native.originalAbility=context.reader.u16(p.speciesAbilities+a.native.species*6+a.native.slot*2);data().abilities.push(a);}});open();};}
 function edit(source){const a=structuredClone(source),p=context&&nativeAbilityProfile(context.reader),n=a.native??={enabled:false,name:a.name.slice(0,16),species:95,slot:0},options=(id,rows,value)=>`<select id="${id}">${rows.map(row=>{const[k,label]=Array.isArray(row)?row:[row,row.replaceAll('_',' ')];return`<option value="${k}" ${String(k)===String(value)?'selected':''}>${esc(label)}</option>`}).join('')}</select>`;api.modal('Ability · '+a.name,`<label>Project name<input id="makerAbilityName" maxlength="40" value="${esc(a.name)}"></label><label>Description<textarea id="makerAbilityDescription" maxlength="1024">${esc(a.description||'')}</textarea></label><label>Template${options('makerAbilityTemplate',[['','Custom'],...Object.entries(ABILITY_TEMPLATES).map(([k,v])=>[k,v.name])],'')}</label><div id="makerAbilityRules"></div><button id="makerAbilityRuleAdd" type="button">＋ Add effect</button><p id="makerAbilityPreview"></p><details open><summary>ROM installation</summary><label class="check"><input id="makerAbilityNative" type="checkbox" ${n.enabled?'checked':''} ${p?'':'disabled'}>Compile a new native ability ID</label><p>Native rules: incoming damage (0–400%), weather (5 turns; rain/sandstorm/bright_sunlight/hail), Intimidate (enemy Attack −1), Rain Dish (self 6.25% in rain), Speed Boost (self Speed +1). Use one action per event trigger. Matching damage rules multiply and round once. Other effects remain designs.</p><label>In-game name<input id="makerAbilityNativeName" maxlength="16" value="${esc(n.name||a.name.slice(0,16))}"></label>${p?`<label>Pokémon${options('makerAbilitySpecies',Array.from({length:p.speciesCount-1},(_,i)=>[i+1,decodeCreatureText(context.reader.bytes,p.speciesNames+(i+1)*11,11)+' · '+(i+1)]),n.species)}</label><label>Ability slot${options('makerAbilitySlot',[[0,'First ability'],[1,'Second ability'],[2,'Hidden ability']],n.slot)}</label>`:''}<p>New IDs start after the source ROM’s reserved ability names. An assignment explicitly changes the selected Pokémon’s ability slot. Existing source records and other ability IDs remain intact.</p></details>`,()=>{collect();if(n.enabled){n.sourceHash=context.hash;const native=data(),map=native.nativeIds[context.hash]??{};const owners=new Set([...Object.values(map),...(p.existing||[]).filter(e=>e.owner!==a.id).map(e=>e.id)]);if(n.id===undefined){n.id=map[a.id]??p.firstCustomId;while(owners.has(n.id)&&map[a.id]!==n.id)n.id++;}if(n.id>1023)throw Error('No custom native ability IDs remain.');n.originalAbility=context.reader.u16(p.speciesAbilities+n.species*6+n.slot*2);validateNativeAbility(a);}api.change(()=>{const s=data();s.nativeIds??={};if(n.enabled){s.nativeIds[context.hash]??={};s.nativeIds[context.hash][a.id]=n.id;}const root=s.abilities.findIndex(v=>v.id===a.id);if(root>=0)s.abilities[root]=a;else{const group=api.project().spriteStudio?.groups.find(g=>g.creature?.abilityDesigns.some(v=>v.id===a.id));if(group)group.creature.abilityDesigns[group.creature.abilityDesigns.findIndex(v=>v.id===a.id)]=a;else s.abilities.push(a);}});open();return false;},'Save ability');
 function collect(){a.name=$('#makerAbilityName').value.trim()||'New ability';a.description=$('#makerAbilityDescription').value;n.enabled=$('#makerAbilityNative').checked;n.name=$('#makerAbilityNativeName').value;if(p){n.species=+$('#makerAbilitySpecies').value;n.slot=+$('#makerAbilitySlot').value;}a.rules.forEach((r,i)=>Object.assign(r,{when:$('#maWhen'+i).value,condition:$('#maIf'+i).value,target:$('#maTarget'+i).value,effect:$('#maEffect'+i).value,value:+$('#maValue'+i).value,parameter:$('#maParam'+i).value}));}
 function preview(){const summary=['normal','fire','water'].flatMap(type=>[false,true].map(contact=>type+' '+(contact?'contact':'non-contact')+' ×'+previewDamageRules(a.rules,{contact,type}))).join(' · ');$('#makerAbilityPreview').textContent='Damage-rule example before other battle effects: '+summary;}
 function draw(){$('#makerAbilityRules').innerHTML=a.rules.map((r,i)=>`<article class="event-step"><label>When${options('maWhen'+i,ABILITY_TRIGGERS,r.when)}</label><label>If${options('maIf'+i,ABILITY_CONDITIONS,r.condition)}</label><label>Target${options('maTarget'+i,['self','ally','enemy','field'],r.target||'self')}</label><label>Effect${options('maEffect'+i,ABILITY_EFFECTS,r.effect)}</label><label>Amount (whole % for damage)<input id="maValue${i}" type="number" step="0.01" value="${r.value}"></label><label>Parameter<input id="maParam${i}" maxlength="80" value="${esc(r.parameter||'')}"></label><button data-ma-remove="${i}" type="button">Remove</button></article>`).join('');for(const b of document.querySelectorAll('[data-ma-remove]'))b.onclick=()=>{collect();a.rules.splice(+b.dataset.maRemove,1);draw()};for(const el of $('#makerAbilityRules').querySelectorAll('input,select'))el.onchange=()=>{collect();preview()};preview();}draw();$('#makerAbilityTemplate').onchange=()=>{collect();const t=ABILITY_TEMPLATES[$('#makerAbilityTemplate').value];if(!t)return;a.name=t.name;a.rules=structuredClone(t.rules);$('#makerAbilityName').value=a.name;n.name=t.name==='Fluffy · all Fire vulnerability'?'Fluffy+':t.name.slice(0,16);$('#makerAbilityNativeName').value=n.name;draw()};$('#makerAbilityRuleAdd').onclick=()=>{collect();if(a.rules.length>=32)throw Error('Use up to 32 effects.');a.rules.push({when:'damage_calculation',condition:'always',target:'self',effect:'damage_multiplier',value:100,parameter:'incoming'});draw()};}
 return{open};}
